//! The generated flash-attention tuning table.
//!
//! # Provenance
//!
//! Mirrors `fa_vec_tuned_table` and the three structs around it, in the
//! reference checkout:
//!
//! - `llama.cpp/ggml/src/ggml-metal/ggml-metal-tuning.cpp` — the table
//! - `llama.cpp/ggml/src/ggml-metal/ggml-metal-tuning.h`   — the structs
//! - `llama.cpp/ggml/src/ggml-metal/ggml-metal-device.h`   — the SKU enum
//!
//! all at v0.4.0 (`5266f24da`).
//!
//! # Generated, not written
//!
//! The C's own comment on the table reads "Generated by
//! `ggml-metal-tuning fa-vec`; do not hand-edit." `scripts/gen-tuning-table`
//! writes the enum, the rows and the count below from the C: 936 rows at
//! v0.3.0, 3,565 at v0.4.0, which is past the point where copying by hand
//! is honest work. It matches **every** row and skips none, checks its
//! count against an independent one, and reproduced the hand-checked v0.3.0
//! table byte for byte. `make tuning-diff` then compares the lookup against
//! the reference's over the whole key space, which is what actually proves
//! the transcription. Do not edit the generated parts; rerun the script.
//!
//! The rows cover nineteen SKUs. The enum is written out in full anyway,
//! because `device_id` is an index into it and dropping the unused names
//! would renumber the rest.

const std = @import("std");
const impl = @import("../impl.zig");

const c = impl.c;

/// Mirrors `enum ggml_metal_device_id` (ggml-metal-device.h:245 @5266f24da). The values are the enum's own ordering, which the table's
/// `device_id` field indexes.
pub const DeviceId = enum(c_uint) {
    generic = 0,
    m1,
    m1_pro,
    m1_max,
    m1_ultra,
    m2,
    m2_pro,
    m2_max,
    m2_ultra,
    m3,
    m3_pro,
    m3_max,
    m3_ultra,
    m4,
    m4_pro,
    m4_max,
    m5,
    m5_pro,
    m5_max,
    m5_ultra,
    a18_pro,
};

/// Mirrors `fa_vec_key_t` (ggml-metal-tuning.h:34 @5266f24da).
///
/// Eight bytes with no padding, which the C's `static_assert` exists to
/// guarantee because `find_cfg` compares keys with `memcmp`.
pub const Key = extern struct {
    device_id: i8,
    dtype: i8,
    dk: i16,
    dv: i16,
    ne11_b: i8,
    ne01_b: i8,
};

/// Mirrors `struct fa_vec_cfg_t` (ggml-metal-tuning.h:45 @5266f24da).
pub const Cfg = extern struct {
    Q: i8,
    NE: i8,
};

/// Mirrors `struct fa_vec_entry_t` (ggml-metal-tuning.h:50 @5266f24da).
pub const Entry = extern struct {
    key: Key,
    cfg: Cfg,
};

