comptime {
    // The C's `static_assert(sizeof(fa_vec_key_t) == 8, …)`, which
    // licenses the `memcmp` the lookup ports as one `u64` compare.
    std.debug.assert(@sizeOf(Key) == 8);
    std.debug.assert(@sizeOf(Cfg) == 2);
    std.debug.assert(@sizeOf(Entry) == 10);
    // The row count the extraction was checked against.
    std.debug.assert(fa_vec_tuned_table.len == 3565);
}

// -----------------------------------------------------------------------------
// Unit Tests

test {
    std.testing.refAllDecls(@This());
}

test "the table is sorted by key, which the generator guarantees" {
    // Not relied on by the lookup -- `find_cfg` is a linear scan -- but a
    // duplicate key would mean the extraction doubled a row, and an
    // out-of-order one that it dropped and re-added.
    var prev: u64 = 0;
    var seen_first = false;
    for (fa_vec_tuned_table) |e| {
        const k: u64 = @bitCast(std.mem.toBytes(e.key));
        if (seen_first) try std.testing.expect(k != prev);
        prev = k;
        seen_first = true;
    }
}
